// Embeds contracts/ukrposhta-ecom.openapi.json (with contracts/overrides.json applied) as a TypeScript module for the simulator.
// The simulator is a test-only entry point; embedding keeps it free of fs access and JSON imports in every bundle format.
//
//   node scripts/gen-ecom-spec.mjs          writes src/simulator/generated/ecomSpec.ts
//   node scripts/gen-ecom-spec.mjs --check  exits 1 when the generated file is out of date
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const source = join(root, 'contracts/ukrposhta-ecom.openapi.json');
const overridesFile = join(root, 'contracts/overrides.json');
const target = join(root, 'src/simulator/generated/ecomSpec.ts');

const spec = JSON.parse(readFileSync(source, 'utf8'));
const overrides = JSON.parse(readFileSync(overridesFile, 'utf8'));

// The documentation (09.03.2026) is newer than the SwaggerHub snapshot: add what it lists and the snapshot lacks.
for (const [name, values] of Object.entries(overrides.enumAdd ?? {})) {
  const schema = spec.components.schemas[name];
  if (!schema?.enum) throw new Error(`overrides.json: ${name} is not an enum schema of the snapshot`);
  schema.enum = [...new Set([...schema.enum, ...values])];
}
if (overrides.nullableOptionalProperties) {
  for (const schema of Object.values(spec.components.schemas)) {
    const required = new Set(schema.required ?? []);
    for (const [name, property] of Object.entries(schema.properties ?? {})) {
      if (required.has(name) || property.nullable) continue;
      if (property.$ref) schema.properties[name] = { nullable: true, allOf: [property] };
      else property.nullable = true;
    }
  }
}
for (const [name, properties] of Object.entries(overrides.replaceProperties ?? {})) {
  const schema = spec.components.schemas[name];
  if (!schema) throw new Error(`overrides.json: schema ${name} not found in the snapshot`);
  for (const [property, replacement] of Object.entries(properties)) {
    if (!schema.properties?.[property])
      throw new Error(`overrides.json: ${name}.${property} not found in the snapshot`);
    schema.properties[property] = replacement;
  }
}
for (const name of overrides.removeRequired ?? []) delete spec.components.schemas[name].required;
for (const [name, properties] of Object.entries(overrides.optionalProperties ?? {})) {
  const schema = spec.components.schemas[name];
  schema.required = (schema.required ?? []).filter(property => !properties.includes(property));
}
const findOperation = operationId => {
  const operation = Object.values(spec.paths)
    .flatMap(item => Object.values(item))
    .find(op => op?.operationId === operationId);
  if (!operation) throw new Error(`overrides.json: operation ${operationId} not found in the snapshot`);
  return operation;
};
const jsonContent = holder => Object.values(holder.content ?? {})[0];
for (const [operationId, change] of Object.entries(overrides.operations ?? {})) {
  const operation = findOperation(operationId);
  if (change.arrayable) {
    const wrap = media => {
      media.schema = { anyOf: [media.schema, { type: 'array', items: media.schema }] };
    };
    wrap(jsonContent(operation.requestBody));
    wrap(jsonContent(operation.responses['200']));
  }
  for (const [status, schema] of Object.entries(change.response ?? {})) {
    operation.responses[status] = {
      ...operation.responses[status],
      content: { '*/*': { schema } },
    };
  }
}
if (overrides.addErrorResponses?.length) {
  spec.components.schemas.UkrposhtaError = {
    type: 'object',
    properties: { code: { type: 'string' }, message: { type: 'string' }, field: { type: 'string' } },
  };
  for (const item of Object.values(spec.paths)) {
    for (const operation of Object.values(item)) {
      if (!operation?.responses) continue;
      for (const status of overrides.addErrorResponses) {
        operation.responses[status] ??= {
          description: 'Error',
          content: { '*/*': { schema: { $ref: '#/components/schemas/UkrposhtaError' } } },
        };
      }
    }
  }
}
for (const [operationId, responses] of Object.entries(overrides.addResponses ?? {})) {
  const operation = findOperation(operationId);
  operation.responses = { ...operation.responses, ...responses };
}
for (const [path, item] of Object.entries(overrides.addPaths ?? {})) {
  if (spec.paths[path]) throw new Error(`overrides.json: ${path} already exists in the snapshot`);
  spec.paths[path] = item;
}
const output = `// @generated by scripts/gen-ecom-spec.mjs from contracts/ukrposhta-ecom.openapi.json + contracts/overrides.json. Do not edit.
import type { OpenApiDocument } from '@shopana/carrier-testing';

// prettier-ignore
export const ukrposhtaEcomSpec = ${JSON.stringify(spec)} as unknown as OpenApiDocument;
`;

if (process.argv.includes('--check')) {
  let current = '';
  try {
    current = readFileSync(target, 'utf8');
  } catch {
    // missing file counts as out of date
  }
  if (current !== output) {
    console.error('src/simulator/generated/ecomSpec.ts is out of date: run `node scripts/gen-ecom-spec.mjs`');
    process.exit(1);
  }
} else {
  writeFileSync(target, output);
  console.log(`Wrote ${target}`);
}
